function cdqPdfAndroidIntentV2273(id,meta,reader){
  const fileId=encodeURIComponent(String(id||''));
  const name=encodeURIComponent(String((meta&&meta.nom)||'Rapport.pdf'));
  const pref=encodeURIComponent(String(reader||'ask'));
  const fallback='https://jprodrigue86.github.io/Rapports--talonnages-CDQ/balance-cdq-android.html';
  return 'intent://open?fileId='+fileId+'&name='+name+'&reader='+pref+
    '#Intent;scheme=cdqpdf;package=ca.balancecdq.android;S.browser_fallback_url='+encodeURIComponent(fallback)+';end';
}

function cdqOuvrirPdfCommeSheetsV2273(id,meta){
  const reader=cdqPdfReaderPreference();

  if(reader==='cdq'){
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  cdqMarquerPdfOuvertV2273(id);

  // Navigation native déclenchée directement dans le tap utilisateur.
  // Balance CDQ Android affiche le vrai sélecteur de compte Google,
  // puis transmet le PDF au lecteur Android choisi.
  const a=document.createElement('a');
  a.href=cdqPdfAndroidIntentV2273(id,meta,reader);
  a.rel='noopener';
  a.style.display='none';
  document.body.appendChild(a);
  a.click();
  a.remove();
  return true;
}

